<h1 class="page-title">Support-Tickets</h1>
<div class="d-flex gap-2 mb-3 flex-wrap"><?php foreach (['' => 'Alle', 'open' => 'Offen', 'in_treatment' => 'In Bearbeitung', 'wait_reply' => 'Wartet', 'closed' => 'Geschlossen'] as $k => $l): ?><a class="btn btn-sm <?= $st === $k ? 'btn-pink' : 'btn-dark2' ?>" href="<?= url('/admin/tickets' . ($k ? '?status=' . $k : '')) ?>"><?= $l ?></a><?php endforeach; ?></div>
<?php foreach ($rows as $r): ?><a class="row-item" href="<?= url('/admin/tickets/' . (int)$r['id']) ?>"><span class="tag gray">#<?= (int)$r['id'] ?></span><b class="flex-grow-1"><?= e($r['subject']) ?> <small class="text-mut">von <?= e($r['username'] ?? '?') ?></small></b><span class="tag"><?= e($r['status']) ?></span><small class="text-mut"><?= ago((int)$r['timestamp']) ?></small></a><?php endforeach; if (!$rows): ?><p class="text-mut">Keine Tickets.</p><?php endif; ?>
